import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';

// Award medal icons
const GoldMedal = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="12" cy="12" r="9" fill="#FFD700" />
    <path d="M12 6L13.8 9.8L18 10.4L15 13.4L15.7 17.6L12 15.6L8.3 17.6L9 13.4L6 10.4L10.2 9.8L12 6Z" fill="#FFA500" />
  </svg>
);

const SilverMedal = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="12" cy="12" r="9" fill="#C0C0C0" />
    <path d="M12 6L13.8 9.8L18 10.4L15 13.4L15.7 17.6L12 15.6L8.3 17.6L9 13.4L6 10.4L10.2 9.8L12 6Z" fill="#A9A9A9" />
  </svg>
);

const BronzeMedal = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="12" cy="12" r="9" fill="#CD7F32" />
    <path d="M12 6L13.8 9.8L18 10.4L15 13.4L15.7 17.6L12 15.6L8.3 17.6L9 13.4L6 10.4L10.2 9.8L12 6Z" fill="#A0522D" />
  </svg>
);

// Empty state message components
const EmptyLeaderboard = () => (
  <div className="text-center py-12">
    <div className="flex justify-center mb-6">
      <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round" className="text-gray-400">
        <path d="M16 6h2c1 0 2 .5 2 2v10c0 1.5-1 2-2 2H8c-1 0-2-.5-2-2V8c0-1.5 1-2 2-2h2"></path>
        <path d="M12 4c0 1.7-1.3 3-3 3h6c-1.7 0-3-1.3-3-3Z"></path>
        <path d="M9 14h6"></path>
        <path d="M9 17h3"></path>
        <path d="M13 17h2"></path>
      </svg>
    </div>
    <h3 className="text-xl font-semibold mb-2 text-gray-600 dark:text-gray-300">You're the First!</h3>
    <p className="text-gray-500 dark:text-gray-400 max-w-md mx-auto">
      It looks like you're the only one on the leaderboard right now. 
      As more people join, you'll be able to see how you compare!
    </p>
  </div>
);

const SingleUserLeaderboard = ({ user, leaderboardType }) => (
  <div className="text-center py-8">
    <div className="max-w-md mx-auto bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
      <div className="flex justify-center mb-4">
        <div className="w-16 h-16 rounded-full bg-blue-100 flex items-center justify-center overflow-hidden border-2 border-blue-500">
          {user.customAvatar ? (
            <img src={user.customAvatar} alt={user.name} className="w-full h-full object-cover" />
          ) : (
            <div className="text-3xl font-bold text-blue-500">{user.name.charAt(0)}</div>
          )}
        </div>
      </div>
      
      <h3 className="text-xl font-bold mb-1">{user.name}</h3>
      <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{user.school}</p>
      
      <div className="mb-6">
        {leaderboardType === 'study' && (
          <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">
            {(user.totalStudyHours || 0).toFixed(1)} <span className="text-sm font-normal">study hours</span>
          </div>
        )}
        {leaderboardType === 'tasks' && (
          <div className="text-2xl font-bold text-green-600 dark:text-green-400">
            {user.completedTasks || 0} <span className="text-sm font-normal">completed tasks</span>
          </div>
        )}
        {leaderboardType === 'streak' && (
          <div className="text-2xl font-bold text-amber-600 dark:text-amber-400">
            {user.streakDays || 0} <span className="text-sm font-normal">days streak</span>
          </div>
        )}
      </div>
      
      <div className="text-gray-600 dark:text-gray-300 text-sm">
        <p className="italic">
          "Keep tracking your progress! Soon you'll be able to compare with others."
        </p>
      </div>
    </div>
  </div>
);

const LeaderboardPage = () => {
  const { getLeaderboard, currentUser } = useAuth();
  const [leaderboardType, setLeaderboardType] = useState('study');
  const [leaderboardData, setLeaderboardData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastFetchTime, setLastFetchTime] = useState(0);

  // Throttled fetch to prevent too many requests
  const fetchLeaderboard = useCallback(async () => {
    const now = Date.now();
    // Only fetch if it's been more than 5 seconds since the last fetch
    // or if we don't have any data yet
    if (now - lastFetchTime > 5000 || leaderboardData.length === 0) {
      setLoading(true);
      setError(null);
      try {
        const data = await getLeaderboard(leaderboardType);
        // Ensure leaderboardData is always an array
        setLeaderboardData(Array.isArray(data) ? data : []);
        setLastFetchTime(now);
      } catch (err) {
        console.error('Error fetching leaderboard:', err);
        setError('Failed to load leaderboard data');
        setLeaderboardData([]);
      } finally {
        setLoading(false);
      }
    }
  }, [getLeaderboard, leaderboardType, lastFetchTime, leaderboardData.length]);

  useEffect(() => {
    fetchLeaderboard();
  }, [fetchLeaderboard]);

  useEffect(() => {
    // Add console log to debug leaderboard data
    if (leaderboardData.length > 0) {
      console.log('Leaderboard data in component:', leaderboardData.map(user => ({
        name: user.name,
        completedTasks: user.completedTasks,
        rank: user.rank
      })));
    }
  }, [leaderboardData]);

  // Change leaderboard type with throttle
  const handleTypeChange = (type) => {
    if (type !== leaderboardType) {
      setLeaderboardType(type);
    }
  };

  // Get medal component based on rank
  const getMedalForRank = (rank) => {
    switch (rank) {
      case 1:
        return <GoldMedal />;
      case 2:
        return <SilverMedal />;
      case 3:
        return <BronzeMedal />;
      default:
        return <span className="inline-block w-6">{rank}</span>;
    }
  };

  // Get appropriate value based on leaderboard type
  const getLeaderboardValue = (user) => {
    console.log('Getting leaderboard value for user:', {
      name: user.name,
      completedTasks: user.completedTasks, 
      valueType: typeof user.completedTasks,
      leaderboardType: leaderboardType
    });
    
    switch (leaderboardType) {
      case 'study':
        return (
          <span>
            {(Number(user.totalStudyHours) || 0).toFixed(1)}
            <span className="text-gray-500 text-xs ml-1">hours</span>
          </span>
        );
      case 'tasks':
        // Ensure we're rendering a number by explicit conversion
        const completedTasks = parseInt(user.completedTasks, 10) || 0;
        return (
          <span>
            {completedTasks}
            <span className="text-gray-500 text-xs ml-1">tasks</span>
          </span>
        );
      case 'streak':
        return (
          <span>
            {Number(user.streakDays) || 0}
            <span className="text-gray-500 text-xs ml-1">days</span>
          </span>
        );
      default:
        return null;
    }
  };

  // Get a neural-gradient class for top 3 users
  const getGradientClass = (rank) => {
    if (rank === 1) return 'bg-gradient-to-r from-amber-300 to-yellow-400 dark:from-amber-400 dark:to-yellow-500';
    if (rank === 2) return 'bg-gradient-to-r from-gray-300 to-gray-400 dark:from-gray-400 dark:to-gray-500';
    if (rank === 3) return 'bg-gradient-to-r from-amber-700 to-yellow-700 dark:from-amber-800 dark:to-yellow-800';
    return '';
  };

  // Check if a user is the current user
  const isCurrentUser = (user) => {
    return currentUser && user.email === currentUser.email;
  };

  // Add a check for empty or single-user leaderboard
  const isSingleUser = leaderboardData.length === 1;
  const isEmpty = leaderboardData.length === 0;

  // Calculate how many users to show in top section and bottom section
  const topUsers = leaderboardData.length >= 3 ? leaderboardData.slice(0, 3) : leaderboardData;
  const remainingUsers = leaderboardData.length > 3 ? leaderboardData.slice(3) : [];

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto px-4 py-8 max-w-4xl"
    >
      <h1 className="text-3xl font-bold mb-6 text-center">Leaderboard</h1>
      
      {/* Leaderboard Type Tabs */}
      <div className="flex justify-center mb-8">
        <div className="flex space-x-2 bg-gray-100 dark:bg-gray-800 p-1 rounded-xl">
          <button
            onClick={() => handleTypeChange('study')}
            className={`px-4 py-2 rounded-lg ${
              leaderboardType === 'study'
                ? 'bg-white dark:bg-gray-700 shadow-md'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            Study Hours
          </button>
          <button
            onClick={() => handleTypeChange('tasks')}
            className={`px-4 py-2 rounded-lg ${
              leaderboardType === 'tasks'
                ? 'bg-white dark:bg-gray-700 shadow-md'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            Completed Tasks
          </button>
          <button
            onClick={() => handleTypeChange('streak')}
            className={`px-4 py-2 rounded-lg ${
              leaderboardType === 'streak'
                ? 'bg-white dark:bg-gray-700 shadow-md'
                : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            Longest Streak
          </button>
        </div>
      </div>

      {/* Loading State */}
      {loading && (
        <div className="flex justify-center items-center py-12">
          <div className="spinner-border animate-spin inline-block w-8 h-8 border-4 rounded-full" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      )}

      {/* Error State */}
      {!loading && error && (
        <div className="text-center py-12">
          <div className="bg-red-100 text-red-700 p-4 rounded-lg inline-block">
            <p>{error}</p>
            <button 
              onClick={() => window.location.reload()} 
              className="mt-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
            >
              Try Again
            </button>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!loading && !error && isEmpty && <EmptyLeaderboard />}

      {/* Single User State */}
      {!loading && !error && isSingleUser && <SingleUserLeaderboard user={leaderboardData[0]} leaderboardType={leaderboardType} />}

      {/* Multiple Users Leaderboard */}
      {!loading && !error && !isEmpty && !isSingleUser && (
        <>
          {/* Top 3 Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            {topUsers.map((user, index) => {
              const rank = index + 1;
              return (
                <motion.div
                  key={user._id || index}
                  whileHover={{ scale: 1.03 }}
                  className={`rounded-xl p-6 shadow-lg ${getGradientClass(rank)} ${
                    isCurrentUser(user) ? 'ring-2 ring-blue-500' : ''
                  }`}
                >
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center">
                      {getMedalForRank(rank)}
                      <span className="ml-2 font-bold text-lg">Rank #{rank}</span>
                    </div>
                    <div className="text-xl font-bold">{getLeaderboardValue(user)}</div>
                  </div>
                  
                  <div className="flex items-center">
                    <div className="w-12 h-12 rounded-full bg-white/30 flex items-center justify-center overflow-hidden">
                      {user.customAvatar ? (
                        <img src={user.customAvatar} alt={user.name} className="w-full h-full object-cover" />
                      ) : (
                        <div className="text-xl font-bold">{user.name?.charAt(0) || '?'}</div>
                      )}
                    </div>
                    <div className="ml-3">
                      <div className="font-bold text-lg truncate max-w-[150px]">{user.name || 'Unknown User'}</div>
                      {isCurrentUser(user) && (
                        <span className="text-xs font-medium px-2 py-1 bg-blue-100 text-blue-800 dark:bg-blue-800 dark:text-blue-100 rounded-full">
                          You
                        </span>
                      )}
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </div>

          {/* Rest of the Leaderboard */}
          {remainingUsers.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
              <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="font-bold text-lg">Other Rankings</h3>
              </div>
              <ul className="divide-y divide-gray-200 dark:divide-gray-700">
                {remainingUsers.map((user) => (
                  <li 
                    key={user._id || user.email} 
                    className={`p-4 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-gray-700 transition ${
                      isCurrentUser(user) ? 'bg-blue-50 dark:bg-blue-900/20' : ''
                    }`}
                  >
                    <div className="flex items-center">
                      <div className="flex items-center justify-center w-8 h-8 mr-4">
                        {getMedalForRank(user.rank)}
                      </div>
                      <div className="flex items-center">
                        <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-600 flex items-center justify-center overflow-hidden mr-3">
                          {user.customAvatar ? (
                            <img src={user.customAvatar} alt={user.name} className="w-full h-full object-cover" />
                          ) : (
                            <div className="text-lg font-bold">{user.name?.charAt(0) || '?'}</div>
                          )}
                        </div>
                        <div>
                          <div className="font-medium">{user.name || 'Unknown User'}</div>
                          {isCurrentUser(user) && (
                            <span className="text-xs font-medium px-2 py-0.5 bg-blue-100 text-blue-800 dark:bg-blue-800 dark:text-blue-100 rounded-full">
                              You
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="text-lg font-bold">{getLeaderboardValue(user)}</div>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </>
      )}
    </motion.div>
  );
};

export default LeaderboardPage; 